{"requestId":"5ebd67b3e2d04ef8950a99da2afefacd","modelId":"deepseek-v4.1-flash","modelName":"Deepseek-V4.1-Flash","isHelperMessage":false,"traceId":"8066db519d57835e2136de78c27a26fc","toolStatus":{"call_00_Vusm5cTC2Bgw8daWadAE2579":{"ready":true,"status":"executed","args":{"filePath":"/workspace/anime/translate_stitch.py","old_str":"def est_translation(im1, im2):
    """估计 im2 相对 im1 的平移 (tx,ty) 与 RANSAC 内点数；不重叠返回 None。

    抗「重复纹理 / 低对比」：灰度做 CLAHE 增强（应对水雾/冰晶等极淡画面），
    再用 RANSAC 拟合相似变换取最大一致集（避免 median 被水/武器重复纹理拉成 0）。
    """
    sift = cv2.SIFT_create()
    # 注意：不要用 CLAHE！它会把水雾/低对比纹理放大，产生大量"位移0"的假匹配，
    # 淹没真实运镜位移（实测镜头2 图1↔图2 会被拉成 0）。原始灰度反而稳。
    g1 = cv2.cvtColor(im1, cv2.COLOR_BGR2GRAY)
    g2 = cv2.cvtColor(im2, cv2.COLOR_BGR2GRAY)
    kp1, des1 = sift.detectAndCompute(g1, None)
    kp2, des2 = sift.detectAndCompute(g2, None)
    if des1 is None or des2 is None:
        return None
    bf = cv2.BFMatcher()
    m = bf.knnMatch(des1, des2, k=2)
    good = [a for a, b in m if a.distance < 0.8 * b.distance]
    if len(good) < 8:
        return None
    src = np.float32([kp1[a.queryIdx].pt for a in good])
    dst = np.float32([kp2[a.trainIdx].pt for a in good])
