def auto_layout(ims, min_matches=6):
    """基于重叠关系自动布局：返回每张图相对画布的全局位置（顺序无关）。"""
    n = len(ims)
    T = {}                      # T[(i,j)] = (dx,dy)：im_j 相对 im_i 的平移
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            r = est_translation(ims[i], ims[j])
            if r and r[2] >= min_matches:
                T[(i, j)] = (r[0], r[1])
    if not T:
        raise RuntimeError("未找到任何重叠对，无法拼接")
    # 锚点：邻居最多的图（链状时即中间那张），与输入顺序无关
    deg = {i: sum(1 for (a, b) in T if a == i) for i in range(n)}
    anchor = max(deg, key=deg.get)
    pos = {anchor: (0.0, 0.0)}
