                dx, dy = T[(i, j)]
                pos[j] = (pos[i][0] - dx, pos[i][1] - dy)
                q.append(j)
    return pos, anchor","new_str":"def _match_pt_ransac(g1, g2):
    sift = cv2.SIFT_create()
