# --------------------------------------------------------------------------- #
# dataset metadata -> reward context
# --------------------------------------------------------------------------- #
_ASSET_CACHE: Dict[str, object] = {}
_ASSET_CACHE_MAX = 4096


def _load_asset(path: str, mode: str):
    key = (path, mode)
    if key in _ASSET_CACHE:
        return _ASSET_CACHE[key]
    from PIL import Image

    img = Image.open(path).convert(mode)
    if len(_ASSET_CACHE) >= _ASSET_CACHE_MAX:
        _ASSET_CACHE.pop(next(iter(_ASSET_CACHE)))
    _ASSET_CACHE[key] = img
    return img


def resolve_context(seam_metas) -> Optional[List[Dict]]:
    """Convert the dataset's `seam_meta` dicts (file paths) into reward context.

    Cached, so the per-training-step cost is one dict lookup after the first
    epoch.  Returns None if `seam_metas` is empty so callers can stay no-op.
    """
    if not seam_metas:
        return None
    out: List[Dict] = []
    for meta in seam_metas:
        if meta is None:
            out.append({})
            continue
        ctx: Dict = {
            "seam_x": meta.get("seam_x", None),
            "vertical": meta.get("vertical", True),
        }
        mask_path = meta.get("mask_path")
        if mask_path:
            ctx["mask"] = _load_asset(mask_path, "L")
        ref_path = meta.get("reference_path")
        if ref_path:
            ctx["reference"] = _load_asset(ref_path, "RGB")
        out.append(ctx)
    return out"},"result":{"status":"success","success":true,"errorCode":"0","result":{"type":"replace_in_file_result","path":"/workspace/anime/MixGRPO/seam_rl/seam_reward.py","addLineCount":47,"removedLines":0,"addedChars":1637,"removedChars":156,"matchCount":1}}}}}

