def reply(h, obj, code=200):
    b = json.dumps(obj, ensure_ascii=False).encode()
    h.send_response(code)
    h.send_header("Content-Type", "application/json; charset=utf-8")
    h.send_header("Content-Length", str(len(b)))
    h.end_headers()
    h.wfile.write(b)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def _authed(self):
        q = parse_qs(urlparse(self.path).query)
        token = self.headers.get("X-Token") or (q.get("token") or [""])[0]
        if token != TOKEN:
            reply(self, {"ok": False, "err": "unauthorized"}, 401)
            return False
        return True

    def do_GET(self):
        u = urlparse(self.path)
        if u.path == "/ping":
            return reply(self, {"ok": True, "host": os.uname().nodename, "cwd": os.getcwd()})
        if not self._authed():
            return
        if u.path == "/read":
            path = (parse_qs(u.query).get("path") or [""])[0]
            try:
                with open(path, "r", errors="replace") as f:
                    data = f.read()
                return reply(self, {"ok": True, "path": path, "size": len(data), "content": data[-200000:]})
            except Exception as exc:
                return reply(self, {"ok": False, "err": str(exc)}, 400)
        return reply(self, {"ok": False, "err": "not found"}, 404)

    def do_POST(self):
        if not self._authed():
            return
        n = int(self.headers.get("Content-Length") or 0)
        try:
            body = json.loads(self.rfile.read(n) or b"{}")
        except Exception as exc:
            return reply(self, {"ok": False, "err": "bad json: %s" % exc}, 400)
        u = urlparse(self.path)
        if u.path == "/exec":
            cmd = body.get("cmd") or ""
            tmo = float(body.get("timeout") or 60)
            try:
                r = subprocess.run(["bash", "-c", cmd], capture_output=True, text=True, timeout=tmo)
                return reply(self, {
                    "ok": True,
                    "code": r.returncode,
                    "stdout": r.stdout[-100000:],
                    "stderr": r.stderr[-20000:],
                })
            except subprocess.TimeoutExpired:
                return reply(self, {"ok": False, "err": "timeout"}, 504)
        if u.path == "/write":
            path = body.get("path") or ""
            content = body.get("content") or ""
            try:
                os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
                with open(path, "w") as f:
                    f.write(content)
                return reply(self, {"ok": True, "path": path, "bytes": len(content)})
            except Exception as exc:
                return reply(self, {"ok": False, "err": str(exc)}, 400)
        return reply(self, {"ok": False, "err": "not found"}, 404)


