    而不是绝对暗度——这样既能去掉暗边也能去掉亮边，且最多只动 max_px 像素。
    """
    g = None
    for _ in range(max_px):
        H, W = img.shape[:2]
        if H < 8 or W < 8:
            break
        g = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY).astype(np.float32)
        bad = {
            "top": (g[0].mean(), g[3].mean()),
            "bottom": (g[-1].mean(), g[-4].mean()),
            "left": (g[:, 0].mean(), g[:, 3].mean()),
            "right": (g[:, -1].mean(), g[:, -4].mean()),
        }
        hit = [k for k, (m, mi) in bad.items()
               if m < mi * rel or m > mi / rel or abs(m - mi) > absdiff]
