            img = img[1:]
        if "bottom" in hit and img.shape[0] > 8:
            img = img[:-1]
        if "left" in hit and img.shape[1] > 8:
            img = img[:, 1:]
        if "right" in hit and img.shape[1] > 8:
            img = img[:, :-1]
    return img


